    def bfs(self, s, t, parent):
        visited = {s}
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v in self.graph[u]:
                val = self.capacity[(u, v)] - self.flow[(u, v)]
                if v not in visited and val > 0:
                    visited.add(v)
                    parent[v] = u
                    if v == t:
                        return True
                    queue.append(v)
        return False

    def edmonds_karp(self):
        max_flow = 0
        parent = {}
        while self.bfs(self.source, self.sink, parent):
            path_flow = float('inf')
            s = self.sink
            while s != self.source:
                p = parent[s]
                val = self.capacity[(p, s)] - self.flow[(p, s)]
                path_flow = min(path_flow, val)
                s = p

            s = self.sink
            while s != self.source:
                p = parent[s]
                self.flow[(p, s)] = path_flow
