    class Edge:
        def __init__(self, to, capacity, reverse_edge):
            self.to = to
            self.capacity = capacity
            self.reverse_edge = reverse_edge
            self.flow = 0

    class Dinic:
        def __init__(self, n):
            self.n = n
            self.graph = [[] for _ in range(n)]

        def add_edge(self, u, v, cap):
            self.graph[u].append(Edge(v, cap, len(self.graph[v])))
            self.graph[v].append(Edge(u, 0, len(self.graph[u]) - 1))

        def bfs(self, s, t, level):
            for i in range(self.n):
                level[i] = -1
            level[s] = 0
            queue = deque([s])
            while queue:
                u = queue.popleft()
                for e in self.graph[u]:
                    if e.capacity - e.flow > 0 and level[e.to] == -1:
                        level[e.to] = level[u] + 1
                        queue.append(e.to)
            return level[t] != -1

        def dfs(self, u, t, pushed, level, ptr):
            if pushed == 0 or u == t:
                return pushed
            for i in range(ptr[u], len(self.graph[u])):
                ptr[u] = i
                e = self.graph[u][i]
                if level[u] + 1 != level[e.to] or e.capacity - e.flow == 0:
                    continue
                tr = self.dfs(e.to, t, min(pushed, e.capacity - e.flow), level, ptr)
                if tr == 0:
                    continue
                e.flow += tr
                e.reverse_edge.flow -= tr
                return tr
            return 0

        def max_flow(self, s, t):
            flow = 0
            level = [-1] * self.n
            while self.bfs(s, t, level):
                ptr = [0] * self.n
                while True:
                    pushed = self.dfs(s, t, float('inf'), level, ptr)
                    if pushed == 0:
