def solution(input_str):
    """
    Determines the winner of the matrix game based on the total sum of cells.

    If the sum of all cell values is odd, Ashish wins.
    If the sum is even, Jeel wins.
    """
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        total = 0
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            total += sum(row)

        # If sum is odd, Ashish (first player) wins
        # If sum is even, Jeel (second player) wins
        if total % 2 == 1:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)
