def solution(s):
    import sys
    from collections import Counter

    parts = s.strip().split('\n')
    if not parts:
        return "0\n"

    n, m = map(int, parts[0].split())
    matrix = [list(parts[i + 1]) for i in range(n)]

    def can_form_palindrome(arr):
        cnt = Counter(arr)
        odds = 0
        for v in cnt.values():
            if v % 2 == 1:
                odds += 1
        return odds <= 1

    def is_palindrome_reorderable(row):
        cnt = Counter(row)
        odds = 0
        for v in cnt.values():
            if v % 2 == 1:
                odds += 1
        return odds <= 1

    def check_submatrix(rows, cols):
        # Each row must be reorderable to palindrome
        for r in range(rows):
            row_slice = ''.join(matrix[r][c:c+cols])
            if not is_palindrome_reorderable(list(row_slice)):
                return False

        # Constraint: either both dimensions even, or height == 1
        height = rows
        width = cols
        if height != 1 and height % 2 != 0 and width % 2 != 0:
            return False

        return True

    count = 0

    for r1 in range(n):
        for c1 in range(m):
            for r2 in range(r1, n):
                for c2 in range(c1, m):
                    height = r2 - r1 + 1
                    width = c2 - c1 + 1

                    # Check each row can form palindrome
                    all_rows_ok = True
                    for r in range(r1, r2 + 1):
                        row_chars = matrix[r][c1:c2+1]
                        cnt = Counter(row_chars)
                        odds = sum(v % 2 for v in cnt.values())
                        if odds > 1:
                            all_rows_ok = False
                            break

                    if not all_rows_ok:
                        continue

                    # Additional constraint: both dimensions even OR height is 1
                    if height > 1 and (height % 2 != 0 and width % 2 != 0):
                        continue

                    count += 1

    return str(count) + '\n'
