Looking at this problem, I need to count squares in a binary matrix. There are two types of squares:
1. Axis-aligned squares (sides parallel to matrix edges)
2. Diagonal squares (sides parallel to matrix diagonals)

A square is defined as a hollow frame with linewidth 1, at least 2×2 for axis-aligned, and must not touch any foreign 1s.

Let me write a solution that counts both types of squares correctly:

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        grid = []
        for i in range(n):
            grid.append(lines[idx + i])
        idx += n

        cnt = 0
        rows, cols = len(grid), len(grid[0])

        # Count axis-aligned squares
        for i in range(rows):
            for j in range(cols):
                # Possible size k (from 1 means 2x2 to ... means k is side_length-1)
                for k in range(1, min(rows - i, cols - j + i, cols - j)):
                    top_left = (i, j)
                    bot_right = (i + k, j + k)

                    # Check top side: all 1s from (i, j) to (i, j+k)
                    is_valid = True
                    for c in range(j, j + k + 1):
                        if grid[i][c] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue

                    # Check bottom side: all 1s from (i+k, j) to (i+k, j+k)
                    for c in range(j, j + k + 1):
                        if grid[i + k][c] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue

                    # Check left side: all 1s from (i, j) to (i+k, j)
                    for r in range(i, i + k + 1):
                        if grid[r][j] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue

                    # Check right side: all 1s from (i, j+k) to (i+k, j+k)
                    for r in range(i, i + k + 1):
                        if grid[r][j + k] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue

                    # Check interior is all 0s (exclusive of border)
                    for r in range(i + 1, i + k):
                        for c in range(j + 1, j + k):
                            if grid[r][c] == '1':
                                is_valid = False
                                break
                        if not is_valid:
                            break
                    if not is_valid:
                        continue

                    # Check non-touching: no 1s touch the square by side or corner
                    # Check all cells that are adjacent to the square's border
                    for r in range(i - 1, i + k + 2):
                        for c in range(j - 1, j + k + 1):
                            if (r, c) != (i, j) and (r, c) != (i + k, j + k) and (r, c) != (i + k, j) and (r, c) != (i, j + k) and not (i <= r <= i + k and j <= c <= j + k):
                                if (grid[r][c] if 0 <= r < rows and 0 <= c < cols else '') == '1':
                                    is_valid = False
                                    break
                        if not is_valid:
                            break
                    if not is_valid:
                        continue

                    cnt += 1

        # Count diagonal diamonds
        for i in range(rows):
            for j in range(cols):
                # Try all possible radii
                for r in range(1, min(i + 1, rows - i, j + 1, cols - j)):
                    # Diamond corners: top, bottom, left, right
                    top = (i - r, j)
                    bottom = (i + r, j)
                    left = (i, j - r)
                    right = (i, j + r)

                    if grid[top][0] != '1' or grid[bottom][0] != '1' or grid[left][0] != '1' or grid[right][0] != '1':
                        continue

                    # Check interior: cells within Manhattan distance < r should not be 1
                    # Actually, need to check: all cells that are NOT corners but within the diamond boundary
                    # Diamond boundary: |r_co - i| + |c_co - j| = r
                    # Interior: |r_co - i| + |c_co - j| < r and (r_co, c_co) not a corner
                    is_valid = True

                    # Check all positions at distance = r
                    for dr in range(-r, r + 1):
                        dc = r - abs(dr)
                        is_valid = is_valid and (grid[i + dr][j + dc] == '1' or 
                                               grid[i - dr][j + dc] == '1' or
                                               grid[i + dr][j - dc] == '1' or
                                               grid[i - dr][j - dc] == '1')

                    if not is_valid:
                        continue

                    # Check non-touching for each corner
                    for tr, tc in [top, bottom, left, right]:
                        if 0 <= tr < rows and 0 <= tc < cols and grid[tr][tc] == '1':
                            # Check 8 neighbors
                            for dr in range(-1, 2):
                                for dc in range(-1, 2):
                                    if dr == 0 and dc == 0:
                                        continue
                                    nr, nc = tr + dr, tc + dc
                                    if 0 <= nr < rows and 0 <= nc < cols:
                                        if grid[nr][nc] == '1':
                                            is_valid = False
                                            break
                                if not is_valid:
                                    break
                        if not is_valid:
                            break

                    if is_valid:
                        cnt += 1

        results.append(str(cnt))

    return '\n'.join(results)
